static int rtl_rx_vlan_en(struct r8152 *tp, bool enable)
{
	int ret;

	switch (tp->version) {
	case RTL_VER_01:
	case RTL_VER_02:
	case RTL_VER_03:
	case RTL_VER_04:
	case RTL_VER_05:
	case RTL_VER_06:
	case RTL_VER_07:
	case RTL_VER_08:
	case RTL_VER_09:
	case RTL_VER_14:
		if (enable)
			ret = ocp_word_set_bits(tp, MCU_TYPE_PLA, PLA_CPCR,
						CPCR_RX_VLAN);
		else
			ret = ocp_word_clr_bits(tp, MCU_TYPE_PLA, PLA_CPCR,
						CPCR_RX_VLAN);
		break;

	case RTL_TEST_01:
	case RTL_VER_10:
	case RTL_VER_11:
	case RTL_VER_12:
	case RTL_VER_13:
	case RTL_VER_15:
	case RTL_VER_16:
	case RTL_VER_17:
	default:
		if (enable)
			ret = ocp_word_set_bits(tp, MCU_TYPE_PLA, PLA_RCR1,
						OUTER_VLAN | INNER_VLAN);
		else
			ret = ocp_word_clr_bits(tp, MCU_TYPE_PLA, PLA_RCR1,
						OUTER_VLAN | INNER_VLAN);
		break;
	}

	return (ret < 0) ? ret : 0;
}
